<script setup>
import { computed, ref, reactive, nextTick, watch } from 'vue'
import { validateProfile, validateAddress } from '../account.js'
import { translate } from '../i18n.js'
import { useRoute, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import { useStorefront } from '../composables/storefront.js'
const route=useRoute()
const {favorites,summary,demoOrders}=useStorefront()
const profile=reactive({name:'Camille Démo',email:'camille@example.test'})
const addresses=ref([]), editing=ref(null), notice=ref(''), error=ref(''), errors=ref({}), pendingRemoval=ref(null), addressForm=ref(null), profileForm=ref(null)
const draft=reactive({label:'',street:'',city:'',postal:'',country:''})
const links=[['account','Vue d’ensemble'],['account-profile','Mon profil'],['account-addresses','Mes adresses'],['account-orders','Mes commandes'],['verify-email','Vérification e-mail']]
const title=computed(()=>links.find(([name])=>name===route.name)?.[1] || 'Mon compte')
const savedProfile=ref(JSON.stringify(profile)), savedDraft=ref('')
let removalTrigger
const dirty=computed(()=>JSON.stringify(profile)!==savedProfile.value||(editing.value!==null&&JSON.stringify(draft)!==savedDraft.value))
const canLeave=()=>!dirty.value||window.confirm(translate('Quitter sans enregistrer les modifications ?'))
onBeforeRouteLeave(canLeave);onBeforeRouteUpdate(canLeave)
watch(()=>route.fullPath,()=>{notice.value='';errors.value={};pendingRemoval.value=null;editing.value=null;Object.assign(profile,JSON.parse(savedProfile.value))})
function edit(index){editing.value=index;Object.keys(draft).forEach(key=>draft[key]=index>=0?addresses.value[index][key]:'');savedDraft.value=JSON.stringify(draft);errors.value={};error.value='';nextTick(()=>document.getElementById('address-label')?.focus())}
async function saveAddress(){
 errors.value=validateAddress(draft)
 if(Object.keys(errors.value).length){await nextTick();addressForm.value?.querySelector('[aria-invalid="true"]')?.focus();return}
 const value=Object.fromEntries(Object.entries(draft).map(([key,value])=>[key,value.trim()]))
 if(editing.value===-1)addresses.value.push(value);else addresses.value[editing.value]=value
 editing.value=null;notice.value='Adresse fictive enregistrée en mémoire pour cet aperçu.';await focusAddresses()
}
async function saveProfile(){errors.value=validateProfile(profile);if(Object.keys(errors.value).length){await nextTick();profileForm.value?.querySelector('[aria-invalid="true"]')?.focus();return}profile.name=profile.name.trim();profile.email=profile.email.trim();savedProfile.value=JSON.stringify(profile);notice.value='Modification simulée en mémoire uniquement.'}
async function focusAddresses(){await nextTick();document.getElementById('addresses-title')?.focus({preventScroll:true})}
async function askRemoval(index,event){removalTrigger=event.currentTarget;pendingRemoval.value=index;await nextTick();document.getElementById('address-confirm')?.focus()}
async function cancelRemoval(){pendingRemoval.value=null;await nextTick();removalTrigger?.focus()}
async function removeAddress(){if(pendingRemoval.value===null)return;addresses.value.splice(pendingRemoval.value,1);pendingRemoval.value=null;editing.value=null;notice.value='Adresse retirée de l’aperçu.';await focusAddresses()}
async function cancelEdit(){editing.value=null;errors.value={};await focusAddresses()}
</script>
<template>
<section class="container section account-page"><span class="eyebrow coral">{{ $t("VOTRE ESPACE NOVASHOP") }}</span><h1>{{ $t(title) }}</h1><p class="account-demo-banner">{{ $t("Compte de démonstration public · aucune authentification. Les données sont fictives et les modifications disparaissent en quittant cet espace. N’utilisez aucune information personnelle réelle.") }}</p>
<div class="account-workspace"><nav class="account-nav" :aria-label="$t(&quot;Navigation du compte&quot;)"><RouterLink v-for="[name,label] in links" :key="name" :to="{name}" :aria-current="route.name===name?'page':undefined">{{ $t(label) }}</RouterLink><RouterLink :to="{name:'favorites'}">{{ $t("Mes favoris") }}</RouterLink><RouterLink :to="{name:'login'}">{{ $t("Voir la connexion") }}</RouterLink></nav><div class="account-panel"><p v-if="notice" role="status">{{ $t(notice) }}</p>
<template v-if="route.name==='account'"><h2>{{ $t("Bienvenue dans votre aperçu.") }}</h2><p>{{ $t("Explorez les écrans du futur espace client.") }}</p><div class="account-stats"><RouterLink :to="{name:'favorites'}"><strong>{{ $t(favorites.length) }}</strong>{{ $t(" favoris locaux") }}</RouterLink><RouterLink :to="{name:'cart'}"><strong>{{ $t(summary.count) }}</strong>{{ $t(" articles au panier") }}</RouterLink></div><p>{{ $t("Aucune commande réelle, aucun moyen de paiement enregistré.") }}</p></template>
<form v-else-if="route.name==='account-profile'" ref="profileForm" @submit.prevent="saveProfile" novalidate><h2>{{ $t("Profil fictif") }}</h2><label for="profile-name">{{ $t("Nom") }}<input id="profile-name" :aria-label="$t('Nom')" :aria-invalid="Boolean(errors.name)" aria-describedby="profile-name-error" v-model="profile.name" maxlength="100" autocomplete="off" required/><span id="profile-name-error" class="field-error">{{ $t(errors.name) }}</span></label><label for="profile-email">{{ $t("Adresse e-mail") }}<input id="profile-email" :aria-label="$t('Adresse e-mail')" :aria-invalid="Boolean(errors.email)" aria-describedby="profile-email-error" v-model="profile.email" type="email" maxlength="254" autocomplete="off" required/><span id="profile-email-error" class="field-error">{{ $t(errors.email) }}</span></label><button class="button button-dark">{{ $t("Simuler la modification") }}</button><h3>{{ $t("Sécurité du compte") }}</h3><p>{{ $t("Le changement de mot de passe et la suppression du compte seront disponibles avec la vérification d’identité côté serveur.") }}</p></form>
<template v-else-if="route.name==='account-addresses'"><h2 id="addresses-title" tabindex="-1">{{ $t("Vos adresses fictives") }}</h2><div v-if="pendingRemoval!==null" class="account-confirm" role="group" aria-labelledby="address-remove-question"><p id="address-remove-question">{{ $t("Supprimer cette adresse ?") }}</p><button id="address-confirm" class="button button-dark" @click="removeAddress">{{ $t("Confirmer la suppression") }}</button><button class="text-link" @click="cancelRemoval">{{ $t("Annuler") }}</button></div><p v-if="!addresses.length">{{ $t("Aucune adresse dans cet aperçu.") }}</p><article v-for="(address,index) in addresses" :key="index" class="demo-address"><h3>{{ address.label }} <small v-if="index===0">{{ $t("· Par défaut") }}</small></h3><p>{{ address.street }}, {{ address.postal }} {{ address.city }}, {{ address.country }}</p><button class="text-link" @click="edit(index)">{{ $t("Modifier") }}</button><button class="text-link" @click="askRemoval(index,$event)">{{ $t("Supprimer") }}</button><button v-if="index>0" class="text-link" @click="addresses.unshift(...addresses.splice(index,1));editing=null">{{ $t("Définir par défaut") }}</button></article><button v-if="editing===null && addresses.length<5" class="button button-dark" @click="edit(-1)">{{ $t("Ajouter une adresse fictive") }}</button><form v-if="editing!==null" ref="addressForm" @submit.prevent="saveAddress" novalidate><h3>{{ $t(editing===-1?'Ajouter':'Modifier') }}{{ $t(" une adresse") }}</h3><label v-for="[key,label] in [['label','Libellé'],['street','Adresse'],['city','Ville'],['postal','Code postal'],['country','Pays']]" :key="key" :for="'address-'+key">{{ $t(label) }}<input :id="'address-'+key" v-model="draft[key]" :aria-label="$t(label)" :aria-invalid="Boolean(errors[key])" :aria-describedby="'address-error-'+key" maxlength="120" autocomplete="off" required/><span :id="'address-error-'+key" class="field-error">{{ $t(errors[key]) }}</span></label><p v-if="error" role="alert" class="field-error">{{ $t(error) }}</p><button class="button button-dark">{{ $t("Enregistrer dans l’aperçu") }}</button><button class="text-link" type="button" @click="cancelEdit">{{ $t("Annuler") }}</button></form></template>
<template v-else-if="route.name==='account-orders'"><h2>{{ $t("Vos simulations de commande") }}</h2><p v-if="!demoOrders.length">{{ $t("Aucune simulation dans cette session. Découvrez le parcours depuis votre panier.") }}</p><article v-for="order in demoOrders" :key="order.reference" class="demo-address"><h3>{{ $t(order.reference) }}</h3><p>{{ $t(order.count) }}{{ $t(" article(s) · ") }}{{ $t(order.status) }}{{ $t(" · Aucun paiement") }}</p><RouterLink class="text-link" :to="{name:'account-order',params:{reference:order.reference}}">{{ $t("Voir le détail") }}</RouterLink></article><RouterLink class="button button-dark" :to="{name:'cart'}">{{ $t("Voir mon panier") }}</RouterLink></template>
<template v-else><h2>{{ $t("Vérification de l’adresse e-mail") }}</h2><p>{{ $t("Aucune adresse vérifiée dans cette démonstration. Le renvoi d’un lien et sa validation seront traités par Laravel avec une session authentifiée et une limitation des tentatives.") }}</p><RouterLink class="text-link" :to="{name:'login'}">{{ $t("Retour à la connexion") }}</RouterLink></template>
</div></div></section>
</template>
